const data = $input.first().json;
const body = data.body || data;
const requested = Number(body['batch_size'] ?? body['Batch size'] ?? 10);
// Apify Company Employees actor caps at 10 in 'all_at_once' mode
const batch_size = Math.min(requested, 10);
return [{ json: { batch_size, batch_size_requested: requested, batch_size_clamped: requested > 10, run_id: 'enrich-' + Date.now() } }];

const all = $input.all();
const companies = [];
const skipped = [];

function deriveSlug(input) {
  if (!input) return '';
  return String(input).replace(/\..*/, '').toLowerCase().replace(/[^a-z0-9-]/g, '');
}
function fromHubspotPage(linkedin) {
  if (!linkedin) return '';
  // Already a LinkedIn URL? extract slug to normalize
  const match = String(linkedin).match(/linkedin\.com\/company\/([^/?]+)/i);
  if (match && match[1]) return 'https://www.linkedin.com/company/' + match[1].toLowerCase();
  return '';
}

for (const item of all) {
  const j = item.json;
  let url = fromHubspotPage(j.linkedin_company_page);
  if (!url) {
    const slug = deriveSlug(j.tam_domain) || deriveSlug(j.domain);
    if (slug) url = 'https://www.linkedin.com/company/' + slug;
  }
  if (!url) {
    skipped.push({ hs_id: j.hs_id, name: j.name });
    continue;
  }
  companies.push({ url, hs_id: j.hs_id, name: j.name });
}

if (skipped.length) {
  console.log('Skipped (no LinkedIn URL derivable): ' + skipped.length + ' — ' + skipped.map(c => c.name).join(', '));
}
if (!companies.length) return [];
return [{ json: { companies, count: companies.length, skipped_count: skipped.length, skipped } }];

const targetRegexes = [
  /\bCRO\b/i, /Chief\s+Revenue\s+Officer/i, /Chief\s+Sales\s+Officer/i,
  /VP\s+(?:of\s+)?Sales/i, /VP\s+(?:of\s+)?Revenue/i,
  /Head\s+of\s+Sales/i, /Head\s+of\s+Revenue/i, /Head\s+of\s+RevOps/i, /Head\s+of\s+GTM/i, /Head\s+of\s+Go[- ]?to[- ]?Market/i,
  /Director\s+of\s+Sales/i, /\bSales\s+Director\b/i,
  /Director\s+of\s+RevOps/i, /VP\s+(?:of\s+)?RevOps/i, /Director\s+of\s+GTM/i, /VP\s+(?:of\s+)?GTM/i, /Revenue\s+Operations\s+Manager/i, /\bRevOps\s+Manager\b/i,
  /\bCEO\b/i, /\bFounder\b/i, /\bCo-?founder\b/i,
];
const denyRegexes = [
  /SDR\s+Manager/i, /BDR\s+Manager/i, /Sales\s+Development\s+Manager/i,
  /Sales\s+Operations\s+Manager/i, /Sales\s+Ops\s+Manager/i, /Outbound\s+Manager/i,
  /\bSenior\s+AE\b/i, /\bSenior\s+SDR\b/i, /\bSenior\s+BDR\b/i,
];
const technicalRoleRegexes = [
  /\bCTO\b/i, /Chief\s+Technology\s+Officer/i,
  /\bCPO\b/i, /Chief\s+Product\s+Officer/i,
  /\bCFO\b/i, /Chief\s+Financial\s+Officer/i,
  /\bCMO\b/i, /Chief\s+Marketing\s+Officer/i,
  /\bCOO\b/i, /Chief\s+Operating\s+Officer/i,
  /VP\s+(?:of\s+)?Engineering/i, /VP\s+(?:of\s+)?Product(?!\s+Marketing)/i,
  /VP\s+(?:of\s+)?Tech/i, /VP\s+(?:of\s+)?Marketing/i, /VP\s+(?:of\s+)?Finance/i,
  /VP\s+(?:of\s+)?People/i, /VP\s+(?:of\s+)?HR/i, /VP\s+(?:of\s+)?Operations/i,
  /Head\s+of\s+(?:Engineering|Product|Tech|Marketing|Finance|People|HR|Operations|Design)/i,
  /Director\s+of\s+(?:Engineering|Product|Tech|Marketing|Finance|People|HR|Operations|Design)/i,
];
const frRegex = /(France|Paris|Lyon|Marseille|Bordeaux|Toulouse|Lille|Nantes|Rennes|Strasbourg|Nice|Grenoble|Montpellier|Sophia[- ]?Antipolis|Aix[- ]?en[- ]?Provence|Île[- ]?de[- ]?France|Hauts[- ]?de[- ]?France)/i;

function norm(s) { return String(s || '').toLowerCase().trim(); }
function getCurrentPos(j) {
  return (j.currentPositions && j.currentPositions[0]) || (j.currentPosition && j.currentPosition[0]) || {};
}
function getTitleHaystack(j) {
  const cp = getCurrentPos(j);
  const parts = [j.title, j.headline, cp.position, cp.title].filter(Boolean);
  return parts.join(' || ');
}
function getLocation(j) {
  if (typeof j.location === 'string') return j.location;
  return j.location?.linkedinText || j.location?.parsed?.text || j.locationName || '';
}
function getCountryCode(j) {
  if (typeof j.location === 'object') {
    return (j.location?.countryCode || j.location?.parsed?.countryCode || '').toUpperCase();
  }
  return '';
}
function getCompanyName(j) {
  const cp = getCurrentPos(j);
  return norm(cp.companyName || cp.company || j.currentCompany?.name);
}
function getCompanyUrl(j) {
  const cp = getCurrentPos(j);
  return norm(cp.companyLinkedinUrl || cp.companyUrl || j.currentCompany?.linkedinUrl || j.currentCompany?.url);
}
function extractSlug(url) {
  return (String(url).split('/company/')[1] || '').split('/')[0].split('?')[0];
}

function isSalesTitle(haystack) {
  return targetRegexes.some(r => r.test(haystack))
      && !denyRegexes.some(r => r.test(haystack))
      && !technicalRoleRegexes.some(r => r.test(haystack));
}

const out = [];
const seen = new Set();
const companies = $('6.5 Aggregate companies for batch').first().json.companies;

let dropped_left_company = 0;
let dropped_no_title = 0;
let dropped_not_sales = 0;
let dropped_not_fr = 0;

for (const item of $input.all()) {
  const j = item.json;
  if (j._company_has_concurrence === true) continue;

  const titleHaystack = getTitleHaystack(j);
  if (!titleHaystack) { dropped_no_title++; continue; }

  const loc = getLocation(j);
  const cc = getCountryCode(j);
  const linkedinUrl = j.linkedinUrl || j.profileUrl || '';
  if (!linkedinUrl || seen.has(linkedinUrl)) continue;
  if (!isSalesTitle(titleHaystack)) { dropped_not_sales++; continue; }

  const isFR = (loc && frRegex.test(loc)) || cc === 'FR';
  if (!isFR) { dropped_not_fr++; continue; }

  // Match employee back to a batch company. Try company name first (more reliable
  // when the actor returns numeric IDs in companyLinkedinUrl), fallback to slug.
  const empCoName = getCompanyName(j);
  const empCoSlug = extractSlug(getCompanyUrl(j));
  const matched = companies.find(c => {
    const cName = norm(c.name);
    const cSlug = extractSlug(c.url);
    if (cName && empCoName && (cName === empCoName || cName.includes(empCoName) || empCoName.includes(cName))) return true;
    if (cSlug && empCoSlug && cSlug === empCoSlug) return true;
    return false;
  });

  if (!matched) {
    dropped_left_company++;
    continue;
  }

  seen.add(linkedinUrl);
  out.push({ json: { ...j, linkedinUrl, _company_hs_id: matched.hs_id, _company_name: matched.name } });
}

console.log('Filter stats — dropped: no_title=' + dropped_no_title + ', not_sales=' + dropped_not_sales + ', not_fr=' + dropped_not_fr + ', left_company=' + dropped_left_company + ' | passed=' + out.length);

return out.slice(0, 200);

function findLastValidJson(text) {
  if (!text) return null;
  const blocks = []; let depth = 0, start = -1;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') { if (depth === 0) start = i; depth++; }
    else if (text[i] === '}') { depth--; if (depth === 0 && start >= 0) { blocks.push([start, i + 1]); start = -1; } }
  }
  for (let i = blocks.length - 1; i >= 0; i--) {
    try {
      const obj = JSON.parse(text.substring(blocks[i][0], blocks[i][1]));
      if (obj && typeof obj === 'object' && 'is_persona' in obj) return obj;
    } catch (e) {}
  }
  for (let i = blocks.length - 1; i >= 0; i--) {
    try { return JSON.parse(text.substring(blocks[i][0], blocks[i][1])); } catch (e) {}
  }
  return null;
}
function clamp(n, min, max) { const x = typeof n === 'number' ? n : 0; return Math.max(min, Math.min(max, x)); }

const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const item = all[i];
  const t = item.json?.content?.[0]?.text || '';
  const v = findLastValidJson(t) || {};
  const orig = $('8. Filter title (FR + target titles)').itemMatching(i)?.json || {};

  const bk = v.score_breakdown || {};
  const tier_pts = clamp(bk.tier_pts, 0, 40);
  const tenure_pts = clamp(bk.tenure_pts, 0, 20);
  const concurrence_pts = clamp(bk.concurrence_pts, 0, 15);
  const signals_pts = clamp(bk.signals_pts, 0, 25);
  const sum = tier_pts + tenure_pts + concurrence_pts + signals_pts;

  const disqNum = v.disqualif_number && /^[1-5]$/.test(String(v.disqualif_number).trim()) ? String(v.disqualif_number).trim() : null;
  const tier = (typeof v.tier === 'number' && v.tier >= 1 && v.tier <= 4) ? v.tier : null;
  const score = disqNum ? 0 : sum;
  const is_persona = !disqNum && score >= 50 && tier !== null;

  // Doubt criteria for Sonnet review (V2)
  // (a) Disqualif #1, #2, #3 cited (Haiku safety bias on investor/recruiter/left-company)
  // (b) Score 40-55 sans disqualif (close to threshold)
  // (c) tier_pts <= 0 mais headline contient 'Sales' / 'Revenue' (potentielle erreur classification tier)
  const headline = String(orig.headline || orig.title || '').toLowerCase();
  const headlineHasSalesKeyword = /sales|revenue|cro|chief|vp|director|head of/i.test(headline);
  const _doubt = (
    disqNum === '1' ||
    disqNum === '2' ||
    disqNum === '3' ||
    (!disqNum && score >= 40 && score <= 55) ||
    (tier_pts <= 0 && headlineHasSalesKeyword)
  );

  const tier_keys = { 1: '1_cro_vp_sales', 2: '2_director_of_sales', 3: '3_revops_lead', 4: '4_ceo_fallback' };

  out.push({
    json: {
      ...orig,
      _verdict: {
        is_persona, score, tier,
        tier_key: tier ? tier_keys[tier] : '',
        score_breakdown: { tier_pts, tenure_pts, concurrence_pts, signals_pts },
        reason: v.reason || '',
        rice_preview: v.rice_preview || '',
        disqualif_number: disqNum,
        tenure_months: typeof v.tenure_months === 'number' ? v.tenure_months : null,
        _doubt,
        _audit: {
          haiku_score: typeof v.score === 'number' ? v.score : null,
          haiku_is_persona: v.is_persona === true,
          haiku_breakdown: bk,
          breakdown_sum_no_disq: sum,
        },
      },
    },
  });
}
return out;

if ($itemIndex !== 0) return [];
const verdicts = $('10.95 Merge confident + reviewed').all() || [];
const total = verdicts.length;
const aggInfo = $('6.5 Aggregate companies for batch').first().json;
const companies = aggInfo.companies || [];
const skipped_count = aggInfo.skipped_count || 0;
let concurrence_count = 0; try { concurrence_count = ($('7.6 Extract concurrence companies').all() || []).reduce((acc, item) => acc + ((item.json?.body?.inputs || []).length), 0); } catch(e) {}
let qualified = 0, disqualified = 0, sonnetReviewed = 0;
const lines = verdicts.map(v => {
  const j = v.json;
  const ver = j._verdict || {};
  if (ver.is_persona) qualified++; else disqualified++;
  if (ver._reviewed_by === 'sonnet') sonnetReviewed++;
  const bk = ver.score_breakdown || {};
  const breakdownStr = (typeof bk.tier_pts === 'number')
    ? ' [T:' + (bk.tier_pts||0) + ' Tn:' + (bk.tenure_pts||0) + ' Cn:' + (bk.concurrence_pts||0) + ' Sg:' + (bk.signals_pts||0) + ']'
    : '';
  const sonnetTag = ver._reviewed_by === 'sonnet' ? ' 🤖' : '';
  const tier = ver.tier_key || '?';
  const cp = (j.currentPositions && j.currentPositions[0]) || {};
  const title = (j.title || j.headline || cp.position || '?').slice(0, 70);
  const compName = j._company_name || '?';
  return '   ' + (ver.is_persona ? '✅' : '❌') + ' *' + (j.firstName || '') + ' ' + (j.lastName || '') + '* — _' + title + '_ — ' + compName + ' (score ' + (ver.score || 0) + ', ' + tier + ')' + breakdownStr + sonnetTag + '\n      _' + (ver.reason || '').slice(0, 180) + '_';
}).join('\n');
const summary = qualified === 0
  ? '🛑 *Aucun persona qualifié — Flow 2 terminé.*\n_' + total + ' personas analysés. Lance Flow 3 pour ingérer plus de TAM ou ajuste rubric._'
  : '✅ *' + qualified + '/' + total + ' persona' + (qualified > 1 ? 's qualifiés' : ' qualifié') + '*\n_Briefs Flow 1 déclenchés en parallèle (1 par persona qualifié)._';
const sonnetNote = sonnetReviewed > 0 ? '\n_🤖 ' + sonnetReviewed + ' verdict(s) re-jugé(s) Sonnet (borderlines)_' : '';
const concurrenceNote = concurrence_count > 0 ? '\n_⚠️ ' + concurrence_count + ' compan' + (concurrence_count > 1 ? 'ies disqualifiées' : 'y disqualifiée') + ' (concurrence interne GTM/RevOps)_' : '';
const skippedNote = skipped_count > 0 ? '\n_⏭️ ' + skipped_count + ' compan' + (skipped_count > 1 ? 'ies skippées' : 'y skippée') + ' (URL LinkedIn non dérivable)_' : '';
const companiesHeader = companies.length > 0 ? '\n*🏢 Companies de ce batch (' + companies.length + ') :*\n' + companies.map(c => '   • ' + c.name).join('\n') + '\n' : '';
const text = '📊 *Flow 2 — Persona Enricher*\n' + total + ' persona' + (total > 1 ? 's analysés' : ' analysé') + sonnetNote + concurrenceNote + skippedNote + companiesHeader + '\n_Légende: T=Tier, Tn=Tenure, Cn=Concurrence, Sg=Signals (sur 100). 🤖 = re-jugé Sonnet_\n\n' + lines + '\n\n' + summary;
return [{ json: { text } }];

const all = $input.all();
const concurrenceTitles = [
  /\bGTM\s+Engineer\b/i, /\bGTM\s+Specialist\b/i,
  /\bRevOps\s+Engineer\b/i, /Revenue\s+Operations\s+Engineer/i,
  /Sales\s+Ops\s+Engineer/i, /Sales\s+Operations\s+Engineer/i,
  /\bGrowth\s+Engineer\b/i, /\bGrowth\s+Manager\b/i, /\bGrowth\s+Lead\b/i, /\bAutomation\s+Engineer\b/i,
  /Marketing\s+Automation\s+(Lead|Manager|Engineer)/i,
];
const sdrPattern = /\bSDR\b|Sales\s+Development\s+Representative|Sales\s+Development(?!\s+(Director|Manager|Lead|Head))/i;
const bdrPattern = /\bBDR\b|Business\s+Development\s+Representative/i;
const csmPattern = /\bCSM\b|Customer\s+Success\s+Manager|Customer\s+Success\s+Specialist|Customer\s+Success\s+Associate|Customer\s+Success\s+Representative/i;
const aePattern = /\bAE\b|Account\s+Executive/i;

function isConcurrence(title) {
  if (!title) return false;
  return concurrenceTitles.some(r => r.test(title));
}
function getCompanyUrl(j) {
  const cp = (j.currentPositions && j.currentPositions[0]) || {};
  return (cp.companyLinkedinUrl || cp.companyUrl || j.currentCompany?.linkedinUrl || j.currentCompany?.url || '').toLowerCase();
}
function extractSlug(url) {
  return (url.split('/company/')[1] || '').split('/')[0].split('?')[0];
}
function getTitle(j) {
  return [j.title, j.headline, j.currentPositions?.[0]?.position, j.currentPositions?.[0]?.title].filter(Boolean).join(' || ');
}

const companies = $('6.5 Aggregate companies for batch').first().json.companies || [];
const compByUrl = {};
for (const c of companies) {
  const slug = extractSlug(String(c.url || '').toLowerCase());
  if (slug) compByUrl[slug] = c;
}

const concurrenceCompanies = new Set();
const salesCountByCompany = {};

for (const item of all) {
  const j = item.json;
  const title = getTitle(j);
  const slug = extractSlug(getCompanyUrl(j));
  if (!slug || !compByUrl[slug]) continue;

  if (!salesCountByCompany[slug]) {
    salesCountByCompany[slug] = { sdr: 0, bdr: 0, csm: 0, ae: 0, total_employees_scraped: 0 };
  }
  salesCountByCompany[slug].total_employees_scraped++;

  if (isConcurrence(title)) concurrenceCompanies.add(slug);
  if (sdrPattern.test(title)) salesCountByCompany[slug].sdr++;
  else if (bdrPattern.test(title)) salesCountByCompany[slug].bdr++;
  if (csmPattern.test(title)) salesCountByCompany[slug].csm++;
  if (aePattern.test(title) && !sdrPattern.test(title) && !bdrPattern.test(title)) salesCountByCompany[slug].ae++;
}

const out = [];
for (const item of all) {
  const j = item.json;
  const slug = extractSlug(getCompanyUrl(j));
  const sc = salesCountByCompany[slug] || { sdr: 0, bdr: 0, csm: 0, ae: 0, total_employees_scraped: 0 };
  out.push({
    json: {
      ...j,
      _company_has_concurrence: concurrenceCompanies.has(slug),
      _company_slug: slug,
      _company_sales_count: sc,
    }
  });
}
console.log('Concurrence: ' + concurrenceCompanies.size + ' | Sales counts: ' + JSON.stringify(salesCountByCompany));
return out;

const companies = $('6.5 Aggregate companies for batch').first().json.companies || [];
const all = $input.all();
const concurrenceSlugs = new Set();
for (const item of all) {
  if (item.json._company_has_concurrence && item.json._company_slug) {
    concurrenceSlugs.add(item.json._company_slug);
  }
}
const inputs = [];
for (const c of companies) {
  const slug = ((c.url || '').toLowerCase().split('/company/')[1] || '').split('/')[0];
  if (concurrenceSlugs.has(slug) && c.hs_id) {
    inputs.push({
      id: c.hs_id,
      properties: {
        tam_status: 'disqualified',
        disqualif_reason: 'Disqualif #6 (Flow 2): GTM Engineer / RevOps / Sales Ops / Growth / Automation Engineer détecté en interne dans la company. Pas de besoin pour notre offre.',
        qualified_reason: '',
        score_icp: 0,
        persona_enrichment_status: 'done',
      },
    });
  }
}
if (!inputs.length) return [];
return [{ json: { body: { inputs } } }];

function findLastValidJson(text) {
  if (!text) return null;
  const blocks = []; let depth = 0, start = -1;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') { if (depth === 0) start = i; depth++; }
    else if (text[i] === '}') { depth--; if (depth === 0 && start >= 0) { blocks.push([start, i + 1]); start = -1; } }
  }
  for (let i = blocks.length - 1; i >= 0; i--) {
    try {
      const obj = JSON.parse(text.substring(blocks[i][0], blocks[i][1]));
      if (obj && typeof obj === 'object' && 'is_persona' in obj) return obj;
    } catch (e) {}
  }
  return null;
}
function clamp(n, min, max) { const x = typeof n === 'number' ? n : 0; return Math.max(min, Math.min(max, x)); }

const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const item = all[i];
  const t = item.json?.content?.[0]?.text || '';
  const v = findLastValidJson(t) || {};
  const orig = $('10.7 IF doubt → Sonnet').itemMatching(i)?.json || {};

  const bk = v.score_breakdown || {};
  const tier_pts = clamp(bk.tier_pts, 0, 40);
  const tenure_pts = clamp(bk.tenure_pts, 0, 20);
  const concurrence_pts = clamp(bk.concurrence_pts, 0, 15);
  const signals_pts = clamp(bk.signals_pts, 0, 25);
  const sum = tier_pts + tenure_pts + concurrence_pts + signals_pts;

  const disqNum = v.disqualif_number && /^[1-5]$/.test(String(v.disqualif_number).trim()) ? String(v.disqualif_number).trim() : null;
  const tier = (typeof v.tier === 'number' && v.tier >= 1 && v.tier <= 4) ? v.tier : null;
  const score = disqNum ? 0 : sum;
  const is_persona = !disqNum && score >= 50 && tier !== null;

  const tier_keys = { 1: '1_cro_vp_sales', 2: '2_director_of_sales', 3: '3_revops_lead', 4: '4_ceo_fallback' };

  // Override Haiku verdict with Sonnet's
  out.push({
    json: {
      ...orig,
      _verdict: {
        is_persona, score, tier,
        tier_key: tier ? tier_keys[tier] : '',
        score_breakdown: { tier_pts, tenure_pts, concurrence_pts, signals_pts },
        reason: '[SONNET REVIEW] ' + (v.reason || ''),
        rice_preview: v.rice_preview || '',
        disqualif_number: disqNum,
        tenure_months: typeof v.tenure_months === 'number' ? v.tenure_months : null,
        _doubt: false,
        _reviewed_by: 'sonnet',
        _audit: {
          ...(orig._verdict?._audit || {}),
          sonnet_score: typeof v.score === 'number' ? v.score : null,
          sonnet_is_persona: v.is_persona === true,
          sonnet_breakdown: bk,
          haiku_was_wrong: orig._verdict?.is_persona !== is_persona,
        },
      },
    },
  });
}
return out;

const total = $input.first().json.total || 0;
const batchSize = $('1c. Normalize Input').first().json.batch_size || 0;
return [{ json: { remaining: total, batch_size: batchSize, run_id: $('1c. Normalize Input').first().json.run_id } }];

const companies = $('6.5 Aggregate companies for batch').first().json.companies || [];
const inputs = companies
  .filter(c => c.hs_id)
  .map(c => ({ id: c.hs_id, properties: { persona_enrichment_status: 'done' } }));
if (!inputs.length) return [];
return [{ json: { body: { inputs } } }];

const all = $input.all();

const byCompany = {};
for (const item of all) {
  const slug = item.json._company_slug || item.json._company_hs_id || '__unknown__';
  if (!byCompany[slug]) byCompany[slug] = [];
  byCompany[slug].push(item);
}

const T1_TIER = '1_cro_vp_sales';
const T2_TIER = '2_director_of_sales';
const T3_TIER = '3_revops_lead';
const T4_TIER = '4_ceo_fallback';
const HIGHER_TIERS = new Set([T1_TIER, T2_TIER, T3_TIER]);

// Defense layer 3: even if Haiku assigned T4 to a technical co-founder, reject promotion.
const technicalRoleRegex = /(\bCTO\b|Chief\s+Technology|Chief\s+Product|Chief\s+Financial|Chief\s+Marketing|Chief\s+Operating|\bCPO\b|\bCFO\b|\bCMO\b|\bCOO\b|VP\s+(?:of\s+)?(?:Engineering|Product(?!\s+Marketing)|Tech|Marketing|Finance|People|HR|Operations)|Head\s+of\s+(?:Engineering|Product|Tech|Marketing|Finance|People|HR|Operations|Design)|Director\s+of\s+(?:Engineering|Product|Tech|Marketing|Finance|People|HR|Operations|Design))/i;

// "Head of GTM" pattern — T2 conditional (only if no T1 in company)
const gtmTitleRegex = /(Head\s+of\s+GTM|Head\s+of\s+Go[- ]?to[- ]?Market|Director\s+of\s+GTM|VP\s+(?:of\s+)?GTM)/i;

function getTitleHaystack(j) {
  const parts = [j.title, j.headline, j.currentPositions?.[0]?.position, j.currentPositions?.[0]?.title].filter(Boolean);
  return parts.join(' || ');
}
function isTechnicalRole(j) { return technicalRoleRegex.test(getTitleHaystack(j)); }
function isGtmTitle(j) { return gtmTitleRegex.test(getTitleHaystack(j)); }

const out = [];

for (const slug in byCompany) {
  const group = byCompany[slug];

  // Step 1: detect if a T1 (Head of Sales / CRO / etc.) is qualified in this company
  const hasT1Qualified = group.some(it => {
    const v = it.json._verdict || {};
    return v.is_persona && v.tier_key === T1_TIER;
  });

  // Step 2: if T1 exists, demote any qualified Head of GTM (T2 conditional) to disqualified
  if (hasT1Qualified) {
    for (const item of group) {
      const v = item.json._verdict || {};
      if (v.is_persona && v.tier_key === T2_TIER && isGtmTitle(item.json)) {
        item.json._verdict = {
          ...v,
          is_persona: false,
          _t2_gtm_demoted: true,
          reason: '[T2 GTM DEMOTED] Head of GTM/Go-to-Market désactivé car un T1 (Head of Sales/CRO/etc.) est qualifié dans la même company. Priorité : toujours T1 > Head of GTM. Original: ' + (v.reason || '')
        };
      }
    }
  }

  // Step 3: existing T4 fallback override (skip if any HIGHER_TIER qualified, including just-demoted T2-GTM still considered if was qualified)
  const hasHigherQualified = group.some(it => {
    const v = it.json._verdict || {};
    return v.is_persona && HIGHER_TIERS.has(v.tier_key);
  });

  if (!hasHigherQualified) {
    const t4Cands = group
      .filter(it => it.json._verdict?.tier_key === T4_TIER)
      .filter(it => !isTechnicalRole(it.json))
      .sort((a, b) => (b.json._verdict?.score || 0) - (a.json._verdict?.score || 0));

    if (t4Cands.length > 0) {
      const chosen = t4Cands[0];
      const orig = chosen.json._verdict || {};
      chosen.json._verdict = {
        ...orig,
        is_persona: true,
        _t4_fallback_promoted: true,
        reason: '[T4 FALLBACK PROMOTED] No T1/T2/T3 qualified in company. CEO/Founder selected as decision-maker fallback (technical co-founders excluded). Original Haiku verdict: ' + (orig.reason || ''),
      };
    }
  }
  out.push(...group);
}
return out;

// Pre-build per-company employees context. KEY FIX: filter employees by
// target company slug, so Haiku doesn't see cross-company contaminated data
// (Apify returns some employees from other companies via LinkedIn cross-matches).

const allEmployees = $('7d. Dedup employees').all() || [];

function extractSlug(url) {
  return ((url || '').toLowerCase().split('/company/')[1] || '').split('/')[0].split('?')[0];
}
function getEmployeeCompanySlug(j) {
  const cp = (j.currentPositions && j.currentPositions[0]) || {};
  return extractSlug(cp.companyLinkedinUrl || cp.companyUrl || j.currentCompany?.linkedinUrl || j.currentCompany?.url || '');
}

// Group all employees by their CURRENT company slug (= the slug visible in their currentPositions)
const employeesBySlug = {};
for (const e of allEmployees) {
  const j = e.json || {};
  const slug = getEmployeeCompanySlug(j);
  if (!slug) continue;
  if (!employeesBySlug[slug]) employeesBySlug[slug] = [];
  employeesBySlug[slug].push({
    title: (j.title || j.headline || j.currentPositions?.[0]?.position || '').slice(0, 100),
    name: ((j.firstName || '') + ' ' + (j.lastName || '')).trim()
  });
}

// Cap each company list to 60 (avoid prompt bloat)
for (const slug in employeesBySlug) {
  employeesBySlug[slug] = employeesBySlug[slug].slice(0, 60);
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;

  // Get THIS persona's company slug → fetch only employees of THAT company
  const personaSlug = j._company_slug || '';
  const companyEmployees = employeesBySlug[personaSlug] || [];

  const profileForHaiku = {
    firstName: j.firstName,
    lastName: j.lastName,
    headline: j.headline,
    location: typeof j.location === 'object' ? (j.location?.linkedinText || j.location?.parsed?.text) : j.location,
    currentPositions: (j.currentPositions || []).slice(0, 3).map(p => ({
      position: p.position || p.title,
      companyName: p.companyName,
      dateRange: p.dateRange,
      duration: p.duration,
    })),
    about: (j.about || '').slice(0, 1500),
    _company_name: j._company_name,
    _company_hs_id: j._company_hs_id,
    _company_slug: j._company_slug,
    linkedinUrl: j.linkedinUrl,
  };

  out.push({
    json: {
      ...j,
      _profileForHaiku: JSON.stringify(profileForHaiku),
      _employeesJson: JSON.stringify(companyEmployees),
      _employeesCount: companyEmployees.length
    }
  });
}
return out;

// Dedup employees by linkedinUrl (some profiles may match BOTH Run A and Run B titles)
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const url = (j.linkedinUrl || j.profileUrl || '').toLowerCase();
  if (!url || seen.has(url)) continue;
  seen.add(url);
  out.push(item);
}
return out;

// 6.6 Filter — keep only companies where Run A returned ≥1 decision-maker.
// Saves Apify cost on Run B by skipping companies that won't qualify.

const employees = $('7. Apify — Company Employees batch').all().map(x => x.json);
const allCompanies = $('6.5 Aggregate companies for batch').first().json.companies || [];

function norm(s) { return String(s || '').toLowerCase().trim(); }

function getCoName(e) {
  if (Array.isArray(e.currentPositions) && e.currentPositions[0]) {
    return norm(e.currentPositions[0].companyName);
  }
  // Fallback: singular currentPosition (older shape)
  if (Array.isArray(e.currentPosition) && e.currentPosition[0]) {
    return norm(e.currentPosition[0].companyName || e.currentPosition[0].company);
  }
  return norm(e.companyName || e.company);
}

const empCount = {};
for (const e of employees) {
  const co = getCoName(e);
  if (!co) continue;
  empCount[co] = (empCount[co] || 0) + 1;
}

const filtered = allCompanies.filter(c => {
  const co = norm(c.name);
  return empCount[co] && empCount[co] > 0;
});

// Fallback: if filter matched 0 companies (e.g. Apify response shape changed),
// keep all companies to avoid breaking the pipeline.
const finalList = filtered.length > 0 ? filtered : allCompanies;

return [{ json: {
  companies: finalList,
  filtered_count: filtered.length,
  total_count: allCompanies.length,
  saved: allCompanies.length - filtered.length,
  fallback_used: filtered.length === 0
}}];
